class RandomByteBatcher:
    def __init__(
        self,
        *,
        batch_size: int,
        seq_len: int,
        device: torch.device,
        sequences: int,
        seed: int,
    ) -> None:
        if batch_size <= 0:
            raise ValueError("batch_size must be positive")
        if seq_len <= 0:
            raise ValueError("seq_len must be positive")
        if sequences <= 0:
            raise ValueError("synthetic sequence count must be positive")
        self.batch_size = batch_size
        self.seq_len = seq_len
        self.device = device
        self.tokenizer = ByteTokenizer()
        generator = torch.Generator(device="cpu").manual_seed(seed)
        self.rows = torch.randint(0, 256, (sequences, seq_len + 1), dtype=torch.long, generator=generator).to(device)
        self.index = 0

    def next(self) -> tuple[Tensor, Tensor]:
        if self.index + self.batch_size > self.rows.shape[0]:
            self.index = 0
        rows = self.rows[self.index : self.index + self.batch_size]
        self.index += self.batch_size
        return rows[:, :-1], rows[:, 1:]

    def next_with_context(self) -> tuple[Tensor, Tensor, Tensor]:
        x, y = self.next()
        return x, y, torch.zeros_like(x)


class AlgorithmicRuleBatcher:
    def __init__(
        self,
        *,
        task: str,
        batch_size: int,
        seq_len: int,
        device: torch.device,
        sequences: int,
        seed: int,
        bit_width: int,
        modulus: int,
        split: str,
        holdout_mode: str,
    ) -> None:
        if batch_size <= 0:
            raise ValueError("batch_size must be positive")
        if seq_len <= 0:
            raise ValueError("seq_len must be positive")
        if sequences <= 0:
            raise ValueError("synthetic sequence count must be positive")
        self.batch_size = batch_size
        self.seq_len = seq_len
        self.device = device
        self.tokenizer = ByteTokenizer()
        generator = torch.Generator(device="cpu").manual_seed(seed)
        if task == "parity":
            total_examples = sequences * seq_len
            if not 1 <= bit_width <= 8:
                raise ValueError("algorithmic_bit_width must be in [1, 8]")
            inputs = torch.randint(0, 2**bit_width, (total_examples,), dtype=torch.long, generator=generator)
            labels = torch.tensor([bin(int(value)).count("1") & 1 for value in inputs.tolist()], dtype=torch.long)
        elif task in {"modular-add", "modular-mul"}:
            total_examples = sequences * seq_len
            if not 2 <= modulus <= 16:
                raise ValueError("algorithmic_modulus must be in [2, 16]")
            left = torch.randint(0, modulus, (total_examples,), dtype=torch.long, generator=generator)
            right = torch.randint(0, modulus, (total_examples,), dtype=torch.long, generator=generator)
            inputs = left * modulus + right
            labels = (left + right) % modulus if task == "modular-add" else (left * right) % modulus
        elif task in {"sequence-modular-add", "sequence-modular-mul", "sequence-delayed-modular-add"}:
            if not 2 <= modulus <= 16:
                raise ValueError("algorithmic_modulus must be in [2, 16]")
            if seq_len % 3 != 0:
                raise ValueError("sequence modular tasks require seq_len divisible by 3")
            pairs = self._modular_pairs(modulus, split=split, holdout_mode=holdout_mode)
            if not pairs:
                raise ValueError("algorithmic split produced no modular pairs")
            triple_count = sequences * (seq_len // 3)
            choice = torch.randint(0, len(pairs), (triple_count,), dtype=torch.long, generator=generator)
            left = torch.tensor([pairs[int(index)][0] for index in choice.tolist()], dtype=torch.long)
            right = torch.tensor([pairs[int(index)][1] for index in choice.tolist()], dtype=torch.long)
            if task == "sequence-delayed-modular-add":
                delayed_left = torch.roll(left, shifts=1)
                delayed_left[0:: seq_len // 3] = 0
                result = (delayed_left + right) % modulus
                op_token = 252
            else:
                result = (left + right) % modulus if task == "sequence-modular-add" else (left * right) % modulus
                op_token = 250 if task == "sequence-modular-add" else 251
            inputs = torch.empty(triple_count * 3, dtype=torch.long)
            labels = torch.empty(triple_count * 3, dtype=torch.long)
            inputs[0::3] = left
            inputs[1::3] = right
            inputs[2::3] = op_token
            labels[0::3] = left
            labels[1::3] = right
            labels[2::3] = result
        else:
            raise ValueError(
                "algorithmic task must be parity, modular-add, modular-mul, sequence-modular-add, sequence-modular-mul, or sequence-delayed-modular-add"
            )
        self.rows_x = inputs.view(sequences, seq_len).to(device)
        self.rows_y = labels.view(sequences, seq_len).to(device)
        self.index = 0

    @staticmethod
    def _modular_pairs(modulus: int, *, split: str, holdout_mode: str) -> list[tuple[int, int]]:
        pairs = [(left, right) for left in range(modulus) for right in range(modulus)]
        if holdout_mode == "none":
            return pairs
        if holdout_mode != "quadrant":
            raise ValueError("algorithmic_holdout_mode must be none or quadrant")
        cutoff = modulus // 2
        heldout = [(left, right) for left, right in pairs if left >= cutoff and right >= cutoff]
        if split == "train":
            return [pair for pair in pairs if pair not in set(heldout)]
        if split == "val":
            return heldout
        raise ValueError("algorithmic split must be train or val")

    def next(self) -> tuple[Tensor, Tensor]:
        if self.index + self.batch_size > self.rows_x.shape[0]:
            self.index = 0
        x = self.rows_x[self.index : self.index + self.batch_size]
        y = self.rows_y[self.index : self.index + self.batch_size]
        self.index += self.batch_size
        return x, y

    def next_with_context(self) -> tuple[Tensor, Tensor, Tensor]:
        x, y = self.next()
        return x, y, torch.zeros_like(x)


def fast_forward_batcher(
    batcher: TokenBatcher | NanochatBestfitBatcher | RandomByteBatcher | AlgorithmicRuleBatcher,
    batches: int,
) -> int:
    if batches < 0:
        raise ValueError("batches must be nonnegative")
    for _ in range(batches):
        batcher.next()
    return batches


def progress_restore_score(val_bpb: float, accuracy: float, accuracy_weight: float) -> float:
    return val_bpb - accuracy_weight * accuracy


def choose_progress_candidate(
    candidates: list[tuple[dict[str, float], dict[str, Tensor]]],
    *,
    accuracy_weight: float,
    min_accuracy: float,
) -> tuple[dict[str, float], dict[str, Tensor]] | None:
    if not candidates:
        return None
    eligible = [
        (metrics, state)
        for metrics, state in candidates
        if float(metrics["accuracy"]) >= min_accuracy
    ]
    if eligible:
        return min(eligible, key=lambda item: (float(item[0]["val_bpb"]), -float(item[0]["accuracy"])))
    return min(
        candidates,
        key=lambda item: progress_restore_score(
            float(item[0]["val_bpb"]),
            float(item[0]["accuracy"]),
            accuracy_weight,
        ),
    )


def choose_best_accuracy_candidate(
    candidates: list[tuple[dict[str, float], dict[str, Tensor]]],
) -> tuple[dict[str, float], dict[str, Tensor]] | None:
    if not candidates:
        return None
    return max(candidates, key=lambda item: (float(item[0]["accuracy"]), -float(item[0]["val_bpb"])))


def choose_best_bpb_candidate(
    candidates: list[tuple[dict[str, float], dict[str, Tensor]]],
    *,
    min_accuracy: float | None = None,
) -> tuple[dict[str, float], dict[str, Tensor]] | None:
    if not candidates:
        return None
    eligible = candidates
    if min_accuracy is not None:
        eligible = [
            (metrics, state)
            for metrics, state in candidates
            if float(metrics["accuracy"]) >= min_accuracy
        ]
    if not eligible:
        eligible = candidates
    return min(eligible, key=lambda item: (float(item[0]["val_bpb"]), -float(item[0]["accuracy"])))


def retain_progress_candidates(
    candidates: list[tuple[dict[str, float], dict[str, Tensor]]],
    *,
    keep_history: bool,
    min_accuracy: float | None = None,
) -> list[tuple[dict[str, float], dict[str, Tensor]]]:
    if keep_history:
        return candidates
    selected: list[tuple[dict[str, float], dict[str, Tensor]]] = []
    for candidate in (
        choose_best_accuracy_candidate(candidates),
        choose_best_bpb_candidate(candidates, min_accuracy=min_accuracy),
    ):
        if candidate is not None and all(candidate is not item for item in selected):
            selected.append(candidate)
    return selected


def choose_restore_candidate(
    *,
    selection: str,
    progress_candidate: tuple[dict[str, float], dict[str, Tensor]] | None,
    accuracy_candidate: tuple[dict[str, float], dict[str, Tensor]] | None,
    bpb_candidate: tuple[dict[str, float], dict[str, Tensor]] | None,
) -> tuple[str, tuple[dict[str, float], dict[str, Tensor]] | None]:
    if selection == "progress":
        return "progress", progress_candidate
    if selection == "accuracy":
        return "accuracy", accuracy_candidate
    if selection == "bpb":
        return "bpb", bpb_candidate
    if selection == "none":
        return "none", None
    raise ValueError("restore selection must be progress, accuracy, bpb, swa, or none")


def average_progress_states(
    candidates: list[tuple[dict[str, float], dict[str, Tensor]]],
    *,
    start_step: int,
    max_candidates: int,
    key_mode: str = "all",
) -> tuple[dict[str, float], dict[str, Tensor]] | None:
    if start_step < 0:
        raise ValueError("swa_start_step must be nonnegative")
    if max_candidates < 0:
        raise ValueError("swa_max_candidates must be nonnegative")
    if key_mode not in {"all", "routing_state", "decoder_only"}:
        raise ValueError("swa_key_mode must be all, routing_state, or decoder_only")
    selected = [candidate for candidate in candidates if int(candidate[0].get("step", 0.0)) >= start_step]
    if max_candidates > 0:
        selected = selected[-max_candidates:]
    if not selected:
        return None
    latest_metrics = dict(selected[-1][0])
    latest_state = selected[-1][1]
    routing_state_keys = (
        "edge_",
        "adjacency",
        "node_bias",
        "node_decay",
        "node_lr_scale",
        "activity_trace",
        "error_trace",
        "error_var_trace",
        "predictor_error_var_trace",
        "token_error_trace",
        "routing_error_trace",
        "pc_error_precision_trace",
        "context_activity_trace",
        "context_error_trace",
        "active_context_error_trace",
    )
    decoder_keys = (
        "decoder_weight",
        "decoder_bias",
        "decoder_quadratic_weight",
        "cosine_decoder_weight",
        "carry_decoder_weight",
    )

    def should_average_key(key: str) -> bool:
        if key_mode == "all":
            return True
        if key_mode == "routing_state":
            return key.startswith(routing_state_keys) or key in routing_state_keys
        if key_mode == "decoder_only":
            return key in decoder_keys
        return False

    averaged: dict[str, Tensor] = {}
    for key, latest_value in latest_state.items():
        if should_average_key(key) and (torch.is_floating_point(latest_value) or torch.is_complex(latest_value)):
            total = torch.zeros_like(latest_value, dtype=torch.float32 if latest_value.dtype != torch.float64 else torch.float64)
            for _, state in selected:
                total = total + state[key].to(dtype=total.dtype)
            averaged[key] = (total / float(len(selected))).to(dtype=latest_value.dtype)
        else:
            averaged[key] = latest_value.detach().clone()
    latest_metrics.update(
        {
            "step": float(latest_metrics.get("step", 0.0)),
            "swa_candidates": float(len(selected)),
            "swa_start_step": float(start_step),
            "swa_key_mode": key_mode,
        }
    )
    return latest_metrics, averaged


def augment_position_context(context_ids: Tensor, position_context_count: int) -> Tensor:
    if position_context_count <= 0:
        return context_ids
    if context_ids.ndim != 2:
        raise ValueError("context_ids must be a 2D tensor")
    positions = torch.arange(context_ids.shape[1], device=context_ids.device, dtype=context_ids.dtype)
    return context_ids * position_context_count + (positions.view(1, -1) % position_context_count)


def perturb_context_ids(
    context_ids: Tensor | None,
    *,
    dropout_prob: float,
    randomize_prob: float,
    context_count: int,
) -> Tensor | None:
    if context_ids is None:
        return None
    if not 0 <= dropout_prob <= 1:
        raise ValueError("dropout_prob must be in [0, 1]")
    if not 0 <= randomize_prob <= 1:
        raise ValueError("randomize_prob must be in [0, 1]")
    if randomize_prob > 0 and context_count <= 0:
        raise ValueError("context_count must be positive when randomize_prob > 0")
    if dropout_prob <= 0 and randomize_prob <= 0:
        return context_ids
    perturbed = context_ids
    if randomize_prob > 0:
        randomize = torch.rand(context_ids.shape, device=context_ids.device) < randomize_prob
        random_context = torch.randint(
            0,
            context_count,
            context_ids.shape,
            device=context_ids.device,
            dtype=context_ids.dtype,
        )
        perturbed = torch.where(randomize, random_context, perturbed)
    if dropout_prob > 0:
        drop = torch.rand(context_ids.shape, device=context_ids.device) < dropout_prob
        perturbed = perturbed.masked_fill(drop, -1)
    return perturbed


def local_lr_factor(step: int, decay_start_step: int, decay_factor: float) -> float:
    if step <= 0:
        raise ValueError("step must be positive")
    if decay_start_step < 0:
        raise ValueError("decay_start_step must be nonnegative")
    if not 0 < decay_factor <= 1:
        raise ValueError("decay_factor must be in (0, 1]")
    if decay_start_step == 0 or step <= decay_start_step:
        return 1.0
    return decay_factor


def scheduled_scale(step: int, start_scale: float, final_scale: float, start_step: int, end_step: int) -> float:
    if step <= 0:
        raise ValueError("step must be positive")
    if start_scale < 0 or final_scale < 0:
        raise ValueError("scales must be nonnegative")
    if start_step < 0 or end_step < 0:
        raise ValueError("schedule steps must be nonnegative")
    if start_step == 0 and end_step == 0:
        return start_scale
    if step <= start_step:
        return start_scale
    if end_step <= start_step or step >= end_step:
        return final_scale
    mix = (step - start_step) / float(end_step - start_step)
    return start_scale + mix * (final_scale - start_scale)


def dopamine_accuracy_signal(
    previous_accuracy: float | None,
    current_accuracy: float,
    *,
    base_threshold: float,
    quadratic_threshold_scale: float,
    pulse_count: int,
    mode: str,
) -> tuple[float, float]:
    if base_threshold < 0:
        raise ValueError("base_threshold must be nonnegative")
    if quadratic_threshold_scale < 0:
        raise ValueError("quadratic_threshold_scale must be nonnegative")
    if pulse_count < 0:
        raise ValueError("pulse_count must be nonnegative")
    if mode not in {"accuracy_drop", "accuracy_gain"}:
        raise ValueError("mode must be accuracy_drop or accuracy_gain")
    threshold = base_threshold + quadratic_threshold_scale * float(pulse_count * pulse_count)
    if previous_accuracy is None:
        return 0.0, threshold
    signal = previous_accuracy - current_accuracy if mode == "accuracy_drop" else current_accuracy - previous_accuracy
    return (signal if signal > threshold else 0.0), threshold


@torch.no_grad()
def evaluate_sequence_answer_positions(
    model: nn.Module,
    batcher: TokenBatcher | RandomByteBatcher | AlgorithmicRuleBatcher,
    *,
    steps: int,
    logit_temperature: float = 1.0,
) -> dict[str, float]:
    if logit_temperature <= 0:
        raise ValueError("logit_temperature must be positive")
    total = 0
    correct = 0
    total_nats = 0.0
    total_bytes = 0.0
    byte_lengths = batcher.tokenizer.token_byte_lengths(model.get_device())  # type: ignore[attr-defined]
    for _ in range(steps):
        x, y = batcher.next()
        logits = model(x)
        answer_logits = logits[:, 2::3, :]
        answer_y = y[:, 2::3]
        scaled_logits = answer_logits / logit_temperature
        loss = F.cross_entropy(scaled_logits.reshape(-1, scaled_logits.shape[-1]), answer_y.reshape(-1), reduction="none")
        pred = answer_logits.argmax(dim=-1)
        correct += int((pred == answer_y).sum().item())
        total += int(answer_y.numel())
        lengths = byte_lengths[answer_y.reshape(-1)]
        total_nats += float((loss * (lengths > 0)).sum().item())
        total_bytes += float(lengths.sum().item())
    return {
        "sequence_answer_accuracy": correct / max(total, 1),
        "sequence_answer_bpb": total_nats / max(math.log(2) * total_bytes, 1e-12),
    }


