class SinglePCModalLanguageModel(nn.Module):
    """Single-layer PC language model with fixed nodes and dynamic local edges."""

    @staticmethod
    def _parse_temporal_prediction_offsets(raw_offsets: str) -> tuple[int, ...]:
        if raw_offsets.strip() == "":
            return ()
        offsets: list[int] = []
        for part in raw_offsets.split(","):
            stripped = part.strip()
            if stripped == "":
                continue
            offsets.append(int(stripped))
        return tuple(offsets)

    @staticmethod
    def _parse_retention_trace_decays(raw_decays: str) -> tuple[float, ...]:
        if raw_decays.strip() == "":
            return ()
        decays: list[float] = []
        for part in raw_decays.split(","):
            stripped = part.strip()
            if stripped == "":
                continue
            decay = float(stripped)
            if not 0 <= decay < 1:
                raise ValueError("retention_trace_decays must be in [0, 1)")
            decays.append(decay)
        return tuple(decays)

